<template>
  <div class="zg-container case-page">
    <PageHeader title="事项办理" description="核对业务事实，获取办理指南，并跟踪需要人工复核的事项。"><template #actions><el-button type="primary" @click="startNew">新建事项</el-button></template></PageHeader>
    <section class="work-panel" v-loading="loading">
      <el-tabs v-model="listTab" class="case-tabs" @tab-change="changeTab"><el-tab-pane :label="`我的事项（${myRows.length}）`" name="mine" /><el-tab-pane v-if="canReview" :label="`待人工复核（${reviewRows.length}）`" name="queue" /></el-tabs>
      <div class="toolbar"><el-input v-model="keyword" clearable placeholder="查找事项名称或编号" style="width:280px" /><el-select v-if="listTab==='mine'" v-model="statusFilter" clearable placeholder="全部状态" style="width:140px"><el-option v-for="(label,value) in statuses" :key="value" :label="label" :value="value" /></el-select><span class="row-count">{{ visibleRows.length }} 项</span><el-button @click="load">刷新</el-button></div>
      <DataState :error="loadError" :empty="!loading && !visibleRows.length" :empty-title="keyword || statusFilter ? '没有符合条件的事项' : listTab==='queue' ? '当前没有待复核事项' : '还没有办理事项'" empty-description="从真实业务场景发起，办理结果与复核意见会保存在这里。" @retry="load"><template #actions><el-button v-if="keyword || statusFilter" @click="keyword='';statusFilter=''">重置筛选</el-button><el-button v-else-if="listTab==='mine'" type="primary" @click="startNew">新建事项</el-button></template>
        <el-table :data="visibleRows" size="small" @row-click="openDetail" class="clickable-table"><el-table-column prop="title" label="事项名称" min-width="240" show-overflow-tooltip /><el-table-column prop="case_no" label="事项编号" width="180" /><el-table-column label="类型" width="110"><template #default="{row}">{{ scenarioLabel(row.scenario) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="statusTone(row.status)" effect="plain">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column v-if="listTab==='queue'" prop="decision_summary" label="待复核原因" min-width="240" show-overflow-tooltip /><el-table-column v-else prop="review_note" label="最新复核意见" min-width="200" show-overflow-tooltip /><el-table-column label="操作" width="100"><template #default="{row}"><el-button text type="primary" @click.stop="openDetail(row)">{{ listTab==='queue' ? '查看并复核' : '查看详情' }}</el-button></template></el-table-column></el-table>
      </DataState>
    </section>

    <el-drawer v-model="newVisible" :title="draftId ? '修正办理事实' : '新建办理事项'" size="min(760px, 95vw)" :close-on-click-modal="!evaluating" :close-on-press-escape="!evaluating" :show-close="!evaluating" :before-close="beforeCloseNew">
      <div class="drawer-flow"><span class="flow-active">1 核对事实</span><span>2 生成办理指南</span><span>3 需要时人工复核</span></div>
      <div v-if="sourceQuestion" class="source-question"><strong>{{ sourceSession ? '关联的咨询原问题' : '办理前的参考问题' }}</strong><p>{{ sourceQuestion }}</p><small>以下正式事实由你填写和确认，咨询中的金额与审批口径不会自动成为申请数据。</small><DataState v-if="sourceError" :error="sourceError" @retry="loadSource(activeSourceId)" /><p v-if="sourceLoading" class="field-note">正在核对本人咨询记录…</p><template v-if="sourceRecord"><div class="source-links"><el-button text type="primary" @click="openSourceConsultation">查看原咨询与引用</el-button></div><div v-if="sourceRecord.related_cases.some(item=>item.case_id!==draftId)" class="source-existing"><strong>这条咨询已有办理记录</strong><div v-for="item in sourceRecord.related_cases.filter(item=>item.case_id!==draftId)" :key="item.case_id"><span>{{ item.title }} · {{ statusLabel(item.status) }}</span><el-button text type="primary" @click="openRelatedCase(item.case_id)">继续已有事项</el-button></div><small>同一事项可继续原草稿；另建前请核对是否为独立业务。</small></div></template></div>
      <DataState v-if="contextError" :error="contextError" @retry="loadContext" />
      <el-alert v-else-if="!form.org_path" type="warning" :closable="false" title="当前账号尚未绑定办理组织，请联系管理员绑定后再发起事项。" />
      <el-alert v-if="draftId" type="info" :closable="false" title="正在编辑已有事项。保存或重新生成指南时会先更新事实，事项编号保持不变。" />
      <el-form :model="form" label-width="100px" class="new-form" :disabled="evaluating">
        <el-form-item label="事项类型" required><el-select v-model="form.scenario" style="width:100%"><el-option v-for="item in scenarios" :key="item.key" :label="item.label" :value="item.key" /></el-select><div class="field-note">{{ ruleCounts[form.scenario] ? `该类型有 ${ruleCounts[form.scenario]} 条已启用规则，是否适用仍需核对事实。` : '该类型暂未建立有效规则，将进入人工复核。' }}</div></el-form-item>
        <el-form-item label="事项名称" required><el-input v-model="form.title" placeholder="例如：XX项目第3号合同变更" /></el-form-item>
        <el-form-item label="办理组织"><el-input :model-value="form.org_name || '尚未绑定'" disabled /></el-form-item>
        <el-form-item label="项目编码"><el-input v-model="form.project_code" placeholder="有明确项目编码时填写" /></el-form-item>
        <div class="money-fields"><el-form-item label="涉及金额"><el-input v-model="form.amount" inputmode="decimal" placeholder="不涉及金额可留空" /></el-form-item><el-form-item label="币种"><el-select v-model="form.currency" clearable placeholder="涉及金额时必填"><el-option label="人民币 CNY" value="CNY" /><el-option label="美元 USD" value="USD" /><el-option label="欧元 EUR" value="EUR" /></el-select></el-form-item></div>
        <el-form-item label="紧急事项"><el-switch v-model="form.urgent" /><span class="field-note inline-note">紧急情况仍需遵守制度审批要求。</span></el-form-item>
        <section v-if="currentFactFields.length" class="business-facts"><h3>办理条件</h3><p class="field-note">这些字段来自本组织可用的已启用规则。按真实情况填写，未核对可留空；系统不会替你选择条件。</p><el-form-item v-for="field in currentFactFields" :key="field.key" :label="field.label"><template v-if="field.kind==='manual'"><span class="field-note">此条件包含复合值，当前需交业务人员人工核验。</span></template><el-input-number v-else-if="field.kind==='number'" v-model="form.businessFacts[field.key]" :controls="false" placeholder="尚未确认" style="width:100%" /><el-select v-else v-model="form.businessFacts[field.key]" clearable placeholder="尚未确认，可留空" style="width:100%"><el-option v-for="option in factOptions(field)" :key="String(option.value)+typeof option.value" :label="option.label" :value="option.value" /></el-select></el-form-item></section>
        <el-form-item label="事实与说明"><el-input v-model="form.description" type="textarea" :rows="5" placeholder="填写事项背景、原因、合同编号及需要说明的条件。" /></el-form-item>
      </el-form>
      <el-checkbox v-model="factsConfirmed" :disabled="evaluating">我已核对上述业务事实，将据此生成办理指南。</el-checkbox>
      <DataState v-if="submitError" :error="submitError" @retry="submit(true)" />
      <template #footer><el-button :disabled="evaluating" @click="closeNew">返回清单</el-button><el-button :disabled="evaluating || !form.org_path || (!!sourceSession && (sourceLoading || !!sourceError))" @click="submit(false)">{{ draftId ? '保存修改' : '保存草稿' }}</el-button><el-button type="primary" :loading="evaluating" :disabled="!form.org_path || !factsConfirmed || (!!sourceSession && (sourceLoading || !!sourceError))" @click="submit(true)">{{ draftId ? '更新事实并生成指南' : '确认并生成指南' }}</el-button></template>
    </el-drawer>

    <el-drawer v-model="detailVisible" :title="selected?.title || '事项详情'" size="min(880px, 95vw)" v-loading="detailLoading"><DataState v-if="detailError" :error="detailError" @retry="resolveDetail(String(route.query.id || ''))" />
      <template v-if="selected"><div class="detail-heading"><el-tag :type="statusTone(selected.status)" effect="plain">{{ statusLabel(selected.status) }}</el-tag><span>{{ selected.case_no }}</span></div>
        <div class="decision-summary" :class="{caution:selected.need_human}"><strong>{{ decisionTitle }}</strong><p>{{ selected.decision_summary || '草稿已保存，尚未进行规则校验。' }}</p></div>
        <section class="detail-section"><h3>申请事实</h3><el-descriptions :column="2" border size="small"><el-descriptions-item label="事项类型">{{ scenarioLabel(selected.scenario) }}</el-descriptions-item><el-descriptions-item label="项目编码">{{ selected.project_code || '未填写' }}</el-descriptions-item><el-descriptions-item label="办理组织">{{ selected.org_name || (selected.org_path===form.org_path ? form.org_name : '组织信息未登记') }}</el-descriptions-item><el-descriptions-item label="金额">{{ amountLabel(selected) }}</el-descriptions-item><el-descriptions-item v-for="item in selectedFactEntries" :key="item.key" :label="item.label">{{ item.value }}</el-descriptions-item></el-descriptions><p class="detail-text">{{ selected.facts?.description || '未填写补充说明' }}</p><section v-if="selected.facts?.source_question" class="consultation-origin"><strong>{{ selected.facts.source_session ? '发起前的咨询' : '办理前的参考问题' }}</strong><p class="detail-text">{{ selected.facts.source_question }}</p><template v-if="selected.requester_id===user.userInfo?.user_id && selected.facts.source_session"><DataState v-if="sourceError" :error="sourceError" @retry="loadSource(activeSourceId)" /><el-button text type="primary" :disabled="sourceLoading || !!sourceError" @click="openSourceConsultation">查看原咨询与引用</el-button><div v-if="sourceRecord" class="origin-citations"><div v-for="cite in sourceRecord.citations" :key="cite.clause_id"><span>{{ cite.file_title }} · {{ cite.clause_no }}</span><el-button text type="primary" @click="router.push({path:`/clause/${cite.clause_id}`,query:{session_id:sourceRecord.session_id}})">回查当时引用</el-button></div><small>咨询引用仅用于回查；本事项的办理结论以校验结果和人工复核为准。</small></div></template><small v-else class="muted">{{ selected.facts.source_session ? '原咨询记录与引用仅向咨询本人开放。' : '仅保留参考文本，未关联已保存的咨询记录。' }}</small></section></section>
        <div class="guide-grid"><section class="detail-section"><h3>审批路径</h3><ol v-if="snapshot.approval_path?.length"><li v-for="step in snapshot.approval_path" :key="step">{{ step }}</li></ol><p v-else class="muted">{{ selected.status==='draft' ? '校验后生成' : '等待业务人员确认' }}</p></section><section class="detail-section"><h3>所需材料</h3><ul v-if="snapshot.materials?.length"><li v-for="item in snapshot.materials" :key="item">{{ item }}</li></ul><p v-else class="muted">尚未形成材料清单</p></section></div>
        <p v-if="snapshot.risk_note" class="risk-note">{{ snapshot.risk_note }}</p>
        <section class="detail-section"><h3>制度依据</h3><article v-for="item in snapshot.evidence || []" :key="item.clause_id" class="evidence-card"><div><strong>{{ item.file_title }}</strong><span>{{ item.file_version }} · {{ item.clause_no }}</span></div><p class="detail-text">{{ item.excerpt }}</p><el-button v-if="item.clause_id" text type="primary" @click="router.push(`/clause/${item.clause_id}`)">查看完整条款</el-button></article><p v-if="!snapshot.evidence?.length" class="muted">未形成可用制度依据</p></section>
        <section v-if="selected.review_note" class="detail-section"><h3>人工复核意见</h3><p class="detail-text">{{ selected.review_note }}</p><small class="muted">{{ formatDate(selected.reviewed_at) }}</small></section>
        <div class="scope-note">本页提供制度办理指南与人工复核记录。后续审批和材料提交按企业实际业务流程执行。</div>
      </template>
      <template #footer><el-button :disabled="evaluating" @click="detailVisible=false">关闭</el-button><el-button v-if="selected" @click="openHandoff">复制办理摘要</el-button><el-button v-if="canEditSelected" type="primary" @click="editSelected">{{ selected?.status==='returned' ? '补充事实并重新提交' : '继续完善草稿' }}</el-button><template v-if="canReview && selected?.status==='review_required'"><el-button @click="beginReview(false)">退回补充</el-button><el-button type="primary" @click="beginReview(true)">填写复核结论</el-button></template></template>
    </el-drawer>

    <el-dialog v-model="handoffVisible" title="办理摘要" width="min(720px, 95vw)"><p class="field-note">可复制给实际办理人员。材料条目不代表已提交，指南不代表已完成企业审批。</p><el-input :model-value="handoffText" type="textarea" :rows="16" readonly aria-label="办理摘要文本" /><template #footer><el-button @click="handoffVisible=false">关闭</el-button><el-button type="primary" :loading="copying" @click="copyHandoff">复制摘要</el-button></template></el-dialog>

    <el-dialog v-model="reviewDialog.visible" :title="reviewDialog.confirmed ? '确认事项办理口径' : '退回补充事实'" width="min(660px, 95vw)" :close-on-click-modal="!reviewDialog.loading" :close-on-press-escape="!reviewDialog.loading" :show-close="!reviewDialog.loading"><p class="review-object">{{ selected?.title }} · {{ selected?.case_no }}</p><el-form label-width="90px"><el-form-item :label="reviewDialog.confirmed ? '复核意见' : '补充要求'" required><el-input v-model="reviewDialog.note" type="textarea" :rows="3" placeholder="明确复核依据、适用范围或需要补充的内容。" /></el-form-item><template v-if="reviewDialog.confirmed"><el-form-item label="审批路径" required><el-input v-model="reviewDialog.approverPath" type="textarea" :rows="3" placeholder="每行填写一个审批环节，按办理顺序排列。" /></el-form-item><el-form-item label="所需材料"><el-input v-model="reviewDialog.materials" type="textarea" :rows="3" placeholder="每行一项材料" /></el-form-item></template></el-form><p v-if="reviewError" class="inline-error" role="alert">{{ reviewError }}</p><template #footer><el-button :disabled="reviewDialog.loading" @click="reviewDialog.visible=false">取消</el-button><el-button :type="reviewDialog.confirmed ? 'primary' : 'warning'" :loading="reviewDialog.loading" @click="submitReview">{{ reviewDialog.confirmed ? '确认并保存复核口径' : '记录补充要求并退回' }}</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useUserStore } from '@/store/user'
import * as caseApi from '@/api/businessCase'
import * as qaApi from '@/api/qa'
import PageHeader from '@/components/PageHeader.vue'
import DataState from '@/components/DataState.vue'
const user=useUserStore(); const route=useRoute(); const router=useRouter()
const loading=ref(false); const evaluating=ref(false); const loadError=ref(''); const contextError=ref(''); const submitError=ref(''); const myRows=ref<caseApi.BusinessCaseOut[]>([]); const reviewRows=ref<caseApi.BusinessCaseOut[]>([])
const reviewError=ref('');const detailError=ref('');const detailLoading=ref(false);let detailVersion=0;const listTab=ref('mine'); const keyword=ref(''); const statusFilter=ref(''); const newVisible=ref(false); const detailVisible=ref(false); const selected=ref<caseApi.BusinessCaseOut|null>(null); const sourceQuestion=ref(''); const factsConfirmed=ref(false); const draftId=ref(''); const ruleCounts=ref<Record<string,number>>({});const factFields=ref<Record<string,caseApi.CaseFactField[]>>({})
const canReview=computed(()=>['R2','R4'].includes(user.role)); const snapshot=computed<Record<string,any>>(()=>{const data=selected.value?.decision_snapshot || {};return {...data,approval_path:data.manual_review?.approver_path?.length ? data.manual_review.approver_path : data.approval_path || data.approver_path || [],materials:data.manual_review?.required_materials || data.materials || data.required_materials || []}})
const canEditSelected=computed(()=>!!selected.value && selected.value.requester_id===user.userInfo?.user_id && ['draft','returned'].includes(selected.value.status))
const initialForm=ref('');const sourceSession=ref('');const baseFacts=ref<Record<string,unknown>>({});const formDirty=computed(()=>newVisible.value && JSON.stringify(form.value)!==initialForm.value)
const sourceRecord=ref<qaApi.QASessionDetail|null>(null);const sourceLoading=ref(false);const sourceError=ref('');let sourceVersion=0;const activeSourceId=computed(()=>newVisible.value ? sourceSession.value : detailVisible.value && selected.value && selected.value.requester_id===user.userInfo?.user_id ? String(selected.value.facts?.source_session || '') : '')
const copying=ref(false);const handoffVisible=ref(false);const handoffText=ref('')
const statuses:Record<string,string>={draft:'草稿',assessed:'已生成指南',review_required:'待人工复核',confirmed:'已人工确认',returned:'已退回补充'}
const scenarios=[{key:'contract_change',label:'合同变更'},{key:'payment',label:'付款申请'},{key:'procurement',label:'采购事项'},{key:'safety',label:'安全事项'},{key:'employment',label:'用工事项'}]
const form=ref({scenario:'contract_change',title:'',org_path:'',org_name:'',project_code:'',amount:'',currency:'',urgent:false,description:'',businessFacts:{} as Record<string,any>})
const currentFactFields=computed(()=>factFields.value[form.value.scenario] || [])
const factLabels:Record<string,string>={urgent:'紧急事项',project_type:'项目类型',procurement_method:'采购方式',employment_type:'用工类型',contract_type:'合同类型',overseas:'境外事项',is_overseas:'境外事项',country:'所在国家',country_scope:'国家范围',org_level:'组织层级'}
const selectedFactEntries=computed(()=>{const hidden=new Set(['description','source_question','source_session','amount','amount_minor','currency','org_path','org_scope','project_code','scenario','title']);return Object.entries(selected.value?.facts || {}).filter(([key])=>!hidden.has(key)).map(([key,value])=>({key,label:(factFields.value[selected.value?.scenario || ''] || []).find(field=>field.key===key)?.label || factLabels[key] || key,value:value===null || value===undefined || value==='' ? '尚未确认' : typeof value==='boolean' ? value ? '是' : '否' : typeof value==='object' ? '复合值，需人工核验' : String(value)}))})
function factOptions(field:caseApi.CaseFactField){const value=form.value.businessFacts[field.key];return value===undefined || value===null || value==='' || field.options.some(option=>option.value===value) ? field.options : [...field.options,{value,label:String(value)+'（已填写，待核对）'}]}
const reviewDialog=ref({visible:false,confirmed:true,note:'',approverPath:'',materials:'',loading:false})
const visibleRows=computed(()=>{ const q=keyword.value.trim().toLowerCase(); return (listTab.value==='queue' ? reviewRows.value : myRows.value).filter(row=>(!q || `${row.title} ${row.case_no}`.toLowerCase().includes(q)) && (listTab.value==='queue' || !statusFilter.value || row.status===statusFilter.value)) })
const decisionTitle=computed(()=>selected.value?.status==='confirmed' ? '业务人员已确认办理口径' : selected.value?.status==='returned' ? '请按复核意见补充事实' : selected.value?.status==='draft' ? '待校验草稿' : selected.value?.need_human ? '等待人工复核' : '规则办理指南')
function scenarioLabel(value:string){return scenarios.find(item=>item.key===value)?.label || value}
function statusLabel(value:string){return statuses[value] || value}
function statusTone(value:string):'success'|'warning'|'info'{return ['confirmed','assessed'].includes(value) ? 'success' : ['review_required','returned'].includes(value) ? 'warning' : 'info'}
function formatDate(value:string|null){return value ? value.slice(0,19).replace('T',' ') : ''}
function amountLabel(row:caseApi.BusinessCaseOut){return row.amount_minor===null ? '未填写金额' : `${(row.amount_minor/100).toLocaleString('zh-CN',{maximumFractionDigits:2})} ${row.currency || ''}`}
async function loadSource(id:string){const version=++sourceVersion;sourceRecord.value=null;sourceError.value='';sourceLoading.value=false;if(!id)return;sourceLoading.value=true;try{const record=await qaApi.sessionDetail(id);if(version===sourceVersion){sourceRecord.value=record;if(newVisible.value && sourceSession.value===id)sourceQuestion.value=record.question}}catch(error:any){if(version===sourceVersion)sourceError.value=error?.response?.status===404 ? '原咨询不存在或不属于当前账号，不能关联办理。' : error?.message || '原咨询读取失败，请重试。'}finally{if(version===sourceVersion)sourceLoading.value=false}}
async function openSourceConsultation(){const id=activeSourceId.value;if(!id || !await allowDiscard())return;newVisible.value=false;router.push({path:'/qa',query:{session:id}})}
async function openRelatedCase(id:string){if(!await allowDiscard())return;newVisible.value=false;router.push({path:'/case',query:{id}});await resolveDetail(id)}
function buildHandoff(){const row=selected.value;if(!row)return '';const data=snapshot.value;const list=(values:string[],empty:string)=>values.length ? values.map((value,index)=>`${index+1}. ${value}`).join('\n') : empty;return [
  `办理摘要：${row.title}`,`事项编号：${row.case_no}`,`当前状态：${statusLabel(row.status)}`,`类型：${scenarioLabel(row.scenario)}`,`办理组织：${row.org_name || '组织名称未登记'}`,`项目编码：${row.project_code || '未填写'}`,`金额：${amountLabel(row)}`,
  ...selectedFactEntries.value.map(item=>`${item.label}：${item.value}`),`事实说明：${row.facts?.description || '未填写'}`,`办理口径：${row.decision_summary || '尚未校验，不具备办理结论'}`,
  '审批路径：',list(data.approval_path || [],'尚未形成路径，需核验'), '需准备材料（尚未确认已提交）：',list(data.materials || [],'尚未形成材料清单'),
  '制度依据：',list((data.evidence || []).map((item:any)=>`${item.file_title} ${item.file_version || ''} ${item.clause_no || ''}\n${item.excerpt || ''}`),'尚无可用依据'),
  ...(row.review_note ? [`人工复核意见：${row.review_note}`,`复核时间：${formatDate(row.reviewed_at)}`] : []),...(row.facts?.source_question ? [`原咨询问题：${row.facts.source_question}`] : []),...(data.risk_note ? [`需注意：${data.risk_note}`] : []),
  '本摘要为制度办理指南与复核记录；后续审批和材料提交按企业实际业务流程执行。',
].join('\n\n')}
function openHandoff(){handoffText.value=buildHandoff();handoffVisible.value=!!handoffText.value}
async function copyHandoff(){if(!handoffText.value || copying.value)return;copying.value=true;try{await navigator.clipboard.writeText(handoffText.value);ElMessage.success('办理摘要已复制，可用于实际流程交接')}catch{ElMessage.info('浏览器未允许直接复制，可在摘要文本中全选复制')}finally{copying.value=false}}
function toMinor(value:string):number|null{const text=value.trim();if(!text)return null;if(!/^\d+(\.\d{1,2})?$/.test(text))throw new Error('金额应为非负数字，最多保留两位小数');const [whole,fraction='']=text.split('.');const amount=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(amount))throw new Error('金额超出可处理范围');return amount}
async function loadContext(){contextError.value='';try{const context=await caseApi.caseContext();const dirty=formDirty.value;form.value.org_path=context.org_name==='未绑定组织' ? '' : context.org_path;form.value.org_name=context.org_name;ruleCounts.value=context.rule_counts || {};factFields.value=context.fact_fields || {};if(newVisible.value && !dirty)initialForm.value=JSON.stringify(form.value)}catch(error:any){contextError.value=error?.message || '无法读取办理组织，请重试。'}}
async function load(openRequested=true){loading.value=true;loadError.value='';try{const [mine,queue]=await Promise.all([caseApi.myCases(),canReview.value ? caseApi.reviewQueue() : Promise.resolve([])]);myRows.value=mine;reviewRows.value=queue;const id=route.query.id;if(openRequested && typeof id==='string')await resolveDetail(id)}catch(error:any){loadError.value=error?.message || '事项清单加载失败'}finally{loading.value=false}}
function changeTab(){router.replace({path:'/case',query:listTab.value==='queue' ? {tab:'queue'} : {}})}
function startNew(){router.push({path:'/case',query:{new:'1',...(listTab.value==='queue' ? {tab:'queue'} : {})}});openNew()}
function openNew(){baseFacts.value={};const chosen=typeof route.query.scenario==='string' && scenarios.some(item=>item.key===route.query.scenario) ? route.query.scenario : 'contract_change';form.value={...form.value,scenario:chosen,title:'',project_code:'',amount:'',currency:'',urgent:false,description:'',businessFacts:{}};sourceQuestion.value=typeof route.query.question==='string' ? route.query.question : '';sourceSession.value=typeof route.query.session==='string' ? route.query.session : '';draftId.value='';factsConfirmed.value=false;submitError.value='';initialForm.value=JSON.stringify(form.value);newVisible.value=true;detailVisible.value=false}
async function allowDiscard(){if(!formDirty.value || !user.isLoggedIn)return true;try{await ElMessageBox.confirm('当前填写的事实尚未保存。离开后这些修改会丢失。','保留办理事实',{confirmButtonText:'放弃修改并离开',cancelButtonText:'继续填写',type:'warning'});return true}catch{return false}}
async function beforeCloseNew(done:()=>void){if(evaluating.value)return;if(await allowDiscard()){done();router.replace({path:'/case',query:listTab.value==='queue' ? {tab:'queue'} : {}})}}
async function closeNew(){if(await allowDiscard()){newVisible.value=false;router.replace({path:'/case',query:listTab.value==='queue' ? {tab:'queue'} : {}})}}
function editSelected(){if(!selected.value || !canEditSelected.value)return;const row=selected.value;baseFacts.value={...row.facts};form.value={scenario:row.scenario,title:row.title,org_path:row.org_path,org_name:row.org_name || (row.org_path===form.value.org_path ? form.value.org_name : '组织信息未登记'),project_code:row.project_code || '',amount:row.amount_minor===null ? '' : (row.amount_minor/100).toFixed(2),currency:row.currency || '',urgent:!!row.facts?.urgent,description:String(row.facts?.description || ''),businessFacts:{...row.facts}};sourceQuestion.value=String(row.facts?.source_question || '');sourceSession.value=String(row.facts?.source_session || '');draftId.value=row.case_id;factsConfirmed.value=false;submitError.value='';initialForm.value=JSON.stringify(form.value);newVisible.value=true;detailVisible.value=false}
async function resolveDetail(id:string){const version=++detailVersion;const local=[...myRows.value,...reviewRows.value].find(row=>row.case_id===id);if(local){selected.value=local;detailError.value='';detailLoading.value=false;detailVisible.value=true;return}selected.value=null;detailError.value='';detailVisible.value=true;detailLoading.value=true;try{const result=await caseApi.caseDetail(id);if(version===detailVersion)selected.value=result}catch(error:any){if(version===detailVersion)detailError.value=error?.response?.status===403 ? '你没有权限查看该事项的事实和复核记录。' : error?.message || '事项不存在或无法读取'}finally{if(version===detailVersion)detailLoading.value=false}}
function openDetail(row:caseApi.BusinessCaseOut){++detailVersion;selected.value=row;detailError.value='';detailLoading.value=false;detailVisible.value=true;router.replace({path:'/case',query:{...(listTab.value==='queue' ? {tab:'queue'} : {}),id:row.case_id}})}
async function submit(evaluate:boolean){if(evaluating.value)return;if(form.value.title.trim().length<2){ElMessage.warning('事项名称至少填写两个字');return}if(!form.value.org_path){ElMessage.warning('当前账号未绑定办理组织');return}if(evaluate && !factsConfirmed.value){ElMessage.warning('请先核对并确认业务事实');return}let amount:number|null;try{amount=toMinor(form.value.amount)}catch(error:any){ElMessage.warning(error.message);return}if(amount!==null && !form.value.currency){ElMessage.warning('涉及金额时请选择币种');return}evaluating.value=true;submitError.value='';try{const payload={scenario:form.value.scenario,title:form.value.title.trim(),org_path:form.value.org_path,project_code:form.value.project_code || null,amount_minor:amount,currency:form.value.currency || null,facts:{...baseFacts.value,...form.value.businessFacts,urgent:form.value.urgent,description:form.value.description.trim(),...(sourceQuestion.value ? {source_question:sourceQuestion.value,source_session:sourceSession.value} : {})}};selected.value=draftId.value ? await caseApi.updateCase(draftId.value,payload) : await caseApi.createCase(payload);draftId.value=selected.value.case_id;initialForm.value=JSON.stringify(form.value);if(evaluate)selected.value=await caseApi.evaluateCase(draftId.value);newVisible.value=false;await load();if(selected.value)openDetail(selected.value);ElMessage.success(evaluate ? '办理结果已保存' : '草稿已保存')}catch(error:any){submitError.value=error?.message || '提交失败，可重试。';if(draftId.value)void load(false)}finally{evaluating.value=false}}
function beginReview(confirmed:boolean){reviewError.value='';reviewDialog.value={visible:true,confirmed,note:'',approverPath:(snapshot.value.approval_path || []).join('\n'),materials:(snapshot.value.materials || []).join('\n'),loading:false}}
async function submitReview(){const d=reviewDialog.value;if(!selected.value || d.loading)return;if(!d.note.trim()){ElMessage.warning('请填写复核意见或补充要求');return}if(d.confirmed && !d.approverPath.trim()){ElMessage.warning('请给出可执行的审批路径');return}d.loading=true;reviewError.value='';try{selected.value=await caseApi.reviewCase(selected.value.case_id,{confirmed:d.confirmed,note:d.note.trim(),approver_path:d.confirmed ? d.approverPath.split(/\n|→/).map(x=>x.trim()).filter(Boolean) : [],required_materials:d.confirmed ? d.materials.split('\n').map(x=>x.trim()).filter(Boolean) : []});d.visible=false;await load();ElMessage.success(d.confirmed ? '复核口径已保存' : '事项已退回')}catch(error:any){reviewError.value=error?.message || '复核提交失败，请保留已填写内容后重试。'}finally{d.loading=false}}
watch(()=>route.query,(query)=>{listTab.value=query.tab==='queue' && canReview.value ? 'queue' : 'mine';if((query.new==='1' || query.mode==='new' || query.scenario) && !newVisible.value)openNew();if(typeof query.id==='string' && (selected.value?.case_id!==query.id || !detailVisible.value))void resolveDetail(query.id)},{immediate:true})
watch(form,()=>{factsConfirmed.value=false},{deep:true})
watch(activeSourceId,(id)=>{void loadSource(id)},{immediate:true})
onBeforeRouteLeave(async()=>{if(evaluating.value){ElMessage.warning('正在保存办理事实，请稍候');return false}return allowDiscard()})
onMounted(()=>{void loadContext();void load()})
</script>
