.case-page{display:flex;flex-direction:column;gap:14px}.case-tabs{padding:8px 16px 0}.case-tabs :deep(.el-tabs__header){margin-bottom:0}.toolbar{padding:12px 16px;display:flex;gap:10px;align-items:center}.row-count{margin-left:auto;color:var(--zg-text-secondary);font-size:12px}.clickable-table :deep(tr){cursor:pointer}.business-facts{border:1px solid var(--zg-border);padding:12px 14px;margin:0 0 18px;background:var(--zg-panel-soft)}.business-facts h3{font-size:14px;margin:0 0 8px}.drawer-flow{display:flex;gap:18px;padding-bottom:14px;border-bottom:1px solid var(--zg-border);color:var(--zg-text-weak);font-size:12px}.flow-active{color:var(--zg-primary);font-weight:600}.source-question{padding:12px 14px;margin:14px 0;background:var(--zg-primary-soft);border-left:3px solid var(--zg-primary)}.source-question p{line-height:1.7;margin:6px 0}.source-question small{color:var(--zg-text-secondary);line-height:1.6}.new-form{padding-top:18px}.field-note{font-size:12px;color:var(--zg-text-secondary);line-height:1.6;margin-top:5px}.inline-note{margin:0 0 0 10px}.money-fields{display:grid;grid-template-columns:1.2fr 1fr}.detail-heading{display:flex;align-items:center;gap:12px;color:var(--zg-text-secondary);margin-bottom:14px;font-size:12px}.decision-summary{background:var(--zg-primary-soft);padding:14px 16px;border-left:3px solid var(--zg-primary);line-height:1.7}.decision-summary.caution{background:#fffaf0;border-left-color:#b77d18}.decision-summary p{margin:5px 0 0}.detail-section{margin-top:20px}.detail-section h3{font-size:14px;margin:0 0 12px;padding-bottom:8px;border-bottom:1px solid var(--zg-border)}.detail-section li{line-height:1.8;margin-bottom:5px}.detail-section ol,.detail-section ul{padding-left:20px}.detail-text{white-space:pre-wrap;line-height:1.8}.guide-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.muted{color:var(--zg-text-secondary);font-size:12px}.risk-note{padding:12px;background:#fffaf0;color:#80500a;line-height:1.7}.evidence-card{padding:12px 14px;border:1px solid var(--zg-border);margin-bottom:10px}.evidence-card>div{display:flex;justify-content:space-between;gap:12px}.evidence-card span{font-size:12px;color:var(--zg-text-secondary)}.scope-note{margin-top:20px;padding:12px;background:var(--zg-panel-soft);color:var(--zg-text-secondary);font-size:12px;line-height:1.7}.review-object{background:var(--zg-panel-soft);padding:12px;margin:0 0 16px}@media(max-width:700px){.money-fields,.guide-grid{grid-template-columns:1fr}.toolbar{flex-wrap:wrap}.drawer-flow{gap:10px;font-size:11px}.evidence-card>div{flex-direction:column;gap:4px}}
